CREATE TABLE IF NOT EXISTS content_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),campaign_id TEXT REFERENCES campaigns(id),title TEXT NOT NULL,content_type TEXT NOT NULL,objective TEXT NOT NULL,audience TEXT NOT NULL,core_message TEXT NOT NULL,platforms_json TEXT NOT NULL DEFAULT '[]',draft_body TEXT NOT NULL DEFAULT '',cta TEXT NOT NULL DEFAULT '',source_refs_json TEXT NOT NULL DEFAULT '[]',asset_refs_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL CHECK(status IN ('IDEA','BRIEFED','DRAFT','QA','CHANGES_REQUIRED','APPROVED','SCHEDULED','PUBLISHED','FAILED','ARCHIVED')),approval_state TEXT NOT NULL DEFAULT 'PENDING',scheduled_at TEXT,published_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_variants(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),content_id TEXT NOT NULL REFERENCES content_items(id),platform TEXT NOT NULL,body TEXT NOT NULL,cta TEXT,status TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_calendar(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),date TEXT NOT NULL,time TEXT NOT NULL,platform TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES content_items(id),campaign_id TEXT REFERENCES campaigns(id),status TEXT NOT NULL,asset_status TEXT NOT NULL,approval_status TEXT NOT NULL,execution_status TEXT NOT NULL);
